const freshUuid=/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i
export async function prepareEscoNationalRefusalIntake(mode:'V'|'VH',field:EscoNationalField,w:IntakeWiring){
 expect(['V','VH']).toContain(mode);expect(['203','205','206','207','208','313','322']).toContain(field)
 const {f,p,checkSentinel,contrlAckProfile,objectAckProfile}=await w.request(mode,true)
 expect(f.mode).toBe(mode);expect(f.app).toBe('23-DGI-PRODAT');expect(p.li).toBeTruthy()
 for(const id of [f.ids.company,f.ids.actor,p.z13.id,contrlAckProfile,objectAckProfile])expect(id).toMatch(freshUuid)
 expect(objectAckProfile).not.toBe(contrlAckProfile)
 for(const family of ['CONTRL','APERAK'] as const){
  const ack=await w.intake(f,p,w.counterpart(p,family))
  expect(await w.consume(f,ack)).toMatchObject({kind:'exact_receipt',sourceMessageId:p.z13.id,
   result:{outcome:'positive',sourceAccepted:family==='APERAK',finalAckReached:family==='APERAK'}})
 }
 expect(await w.permission(f,p)).toMatchObject({status:'waiting_for_customer_approval'})
 await w.noAccess(f,p);checkSentinel()
 const status=mode==='V'?'A13':'A76',healthyWire=w.render(f,p,status)
 const basis={sender:f.receiver,receiver:f.sender,li:p.li,status,healthyWire} as const
 const raw=omitEscoNationalField(healthyWire,field,basis)
 // Freeze edition, actor and all old source-rule/identity ledgers BEFORE
 // mail/canonical INSERT; returned plain rows never mint a private capability.
 const identityBeforeIntake=captureEscoNationalIdentityPrestate(w.sql).basis
 const previousOutbox=structuredClone(w.fullOutbox(f)),beforeMail=Date.now()
 const input=await w.retained(f,raw)
 expect(input).toMatchObject({companyId:f.ids.company,actorUserId:f.ids.actor,environment:'test'})
 for(const id of [input.inboundEmailMessageId,input.parseResultId])expect(id).toMatch(freshUuid)
 expect(input.parsed).toEqual(parseEdifactPayload(raw));const sealedInput=structuredClone(input)
 const started=Date.now(),id=await createInboundEdielMessage(input),completed=Date.now()
 expect(id).toMatch(freshUuid);expect(id).not.toBe(p.z13.id)
 if(!id)throw Error('esco_national_public_intake_required')
 const sourceBefore=w.sql<EdielMessageRow&{immutable_payload_hash:string}>(`SELECT to_jsonb(m) FROM public.ediel_messages m WHERE id=${w.lit(id)}`)
 expect(Object.keys(sourceBefore).sort()).toEqual([...sourceColumns].sort())
 expect(sourceBefore).toMatchObject({id,company_id:f.ids.company,environment:'test',direction:'inbound',message_standard:'edifact',
  message_family:'PRODAT',message_code:'Z14',raw_payload:raw,immutable_payload_hash:createHash('sha256').update(raw,'utf8').digest('hex'),
  inbound_email_message_id:input.inboundEmailMessageId,mailbox_message_id:input.inboundEmailMessageId,application_reference:'23-DGI-PRODAT'})
 const arrival=parseSourceReceiptInstant(sourceBefore.message_received_at),sent=parseSourceReceiptInstant(p.z13.message_sent_at)
 expect(arrival).not.toBeNull();expect(sent).not.toBeNull()
 if(arrival===null||sent===null)throw Error('esco_national_retained_mail_clock_required')
 expect(arrival>sent&&arrival>=BigInt(beforeMail)*BigInt(1000)&&arrival<(BigInt(completed)+BigInt(1))*BigInt(1000)).toBe(true)
 expect(input).toEqual(sealedInput);expect(await getEdielMessageById(id)).toEqual(sourceBefore)
 expect(w.fullOutbox(f)).toEqual(previousOutbox);await w.noAccess(f,p);checkSentinel()
 return{f,p,checkSentinel,contrlAckProfile,objectAckProfile:objectAckProfile!,basis,healthyWire,raw,input:sealedInput,
  sourceBefore:structuredClone(sourceBefore),identityBeforeIntake:structuredClone(identityBeforeIntake),intakeWindow:[started,completed] as const}
}

