// A closed single READ statement; caller uses the unchanged native one-string port.
const eventReadQuery=`WITH catalog AS (
 SELECT c.relname,a.attnum,jsonb_build_object('name',a.attname,'typeSchema',tn.nspname,'typeName',t.typname,'notNull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) AS col
 FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_class c ON c.oid=a.attrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace
 JOIN pg_catalog.pg_type t ON t.oid=a.atttypid JOIN pg_catalog.pg_namespace tn ON tn.oid=t.typnamespace
 LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE n.nspname='public' AND c.relname IN ('ediel_messages','ediel_message_events','ediel_processing_runs','ediel_decision_traces','ediel_sla_timers') AND a.attnum>0 AND NOT a.attisdropped
), catalogs AS (SELECT relname,jsonb_agg(col ORDER BY attnum) cols FROM catalog GROUP BY relname)
SELECT jsonb_build_object('catalog',(SELECT jsonb_object_agg(relname,cols) FROM catalogs),
 'sources',(SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]'::jsonb) FROM public.ediel_messages m),
 'events',(SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]'::jsonb) FROM public.ediel_message_events m),
 'runs',(SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]'::jsonb) FROM public.ediel_processing_runs m),
 'traces',(SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]'::jsonb) FROM public.ediel_decision_traces m),
 'timers',(SELECT COALESCE(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]'::jsonb) FROM public.ediel_sla_timers m))`
