function eventClosed(row:EventRow,table:keyof typeof eventCatalog){expect(Object.keys(row).sort()).toEqual(eventCatalog[table].map(c=>c.name).sort())}
function eventSort(rows:EventRow[]){return [...rows].sort((a,b)=>String(a.id).localeCompare(String(b.id)))}
function eventInstant(value:unknown){const v=parseSourceReceiptInstant(value);expect(v).not.toBeNull();if(v===null)throw Error('esco_event_clock_required');return v}
function eventClock<T>(value:T,window:readonly[number,number]){const t=eventInstant(value);expect(t>=BigInt(window[0])*BigInt(1000)&&t<(BigInt(window[1])+BigInt(1))*BigInt(1000)).toBe(true);return value}
function eventFresh(id:unknown,old:EventRow[],seen:Set<string>){expect(id).toMatch(freshUuid);expect(old.some(r=>r.id===id)).toBe(false);expect(seen.has(String(id))).toBe(false);seen.add(String(id));return id}
function eventRead(read:EventRead):EventFrame{
 const frame=structuredClone(read(eventReadQuery)) as EventFrame
 expect(Object.keys(frame).sort()).toEqual(['catalog','sources','events','runs','traces','timers'].sort());expect(frame.catalog).toEqual(eventCatalog)
 for(const [key,table] of Object.entries(eventTables)){
  const rows=frame[key as keyof typeof eventTables];expect(Array.isArray(rows)).toBe(true);const ids=rows.map(r=>r.id);expect(new Set(ids).size).toBe(ids.length)
  for(const r of rows)eventClosed(r,table)
 }
 return frame
}
function eventAdded(old:EventRow[],now:EventRow[],replace?:EventRow){
 const byId=new Map(now.map(r=>[r.id,r]));for(const r of old)expect(byId.get(r.id)).toEqual(replace?.id===r.id?replace:r)
 return now.filter(r=>!old.some(o=>o.id===r.id))
}
