type NationalBusinessColumn={name:string;position:number;type:string;notNull:boolean;default:string|null;generated:string}
type NationalBusinessFrame={version:2;schema:Record<string,NationalBusinessColumn[]>;schemaText:string;tables:Record<string,string[]>}
const nationalBusinessTables=[
 'public.companies','public.tenant_actor_roles','public.tenant_actor_identifiers','public.tenant_ediel_profiles',
 'public.ediel_actor_settings','public.tenant_counterparty_relations','public.company_memberships','public.user_permissions',
 'public.company_capabilities','public.customers','public.customer_sites','public.metering_points','public.grid_owners',
 'public.ediel_service_assignments','public.ediel_service_evidence','public.ediel_assignment_permission_links',
 'public.ediel_data_access_grants','public.ediel_service_history','public.metering_permissions','public.metering_permission_sites',
 'public.customer_supply_periods','public.supplier_switch_requests','public.meter_reading_series','public.meter_reading_values',
 'public.communication_routes','public.ediel_route_profiles','public.outbound_requests','public.ediel_message_intents',
 'public.platform_market_actors','public.platform_actor_roles','public.user_profiles','public.ediel_permission_events',
 'gridex_service_administration.scope_versions','gridex_ediel_services.artifacts','gridex_ediel_services.issuer_representations',
 'gridex_ediel_services.reviews','gridex_service_permission.origins','gridex_ediel_transport.attempts',
 'gridex_service_administration.permission_request_owners','gridex_service_permission.request_timing_receipts',
 'gridex_received_sources.permission_effect_receipts','gridex_received_sources.permission_effect_transitions_v1',
 'gridex_ediel_services.issuer_keys','gridex_ediel_services.issuer_revocations','gridex_ediel_exports.jobs',
 'gridex_service_administration.commands',
] as const
const nationalBusinessQuery=`WITH names(name) AS (VALUES ${nationalBusinessTables.map(t=>`('${t}')`).join(',')}),
columns AS (SELECT n.name,a.attnum,jsonb_build_object('name',a.attname,'position',a.attnum,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid),'generated',a.attgenerated) AS descriptor
 FROM names n JOIN pg_catalog.pg_attribute a ON a.attrelid=pg_catalog.to_regclass(n.name)
 LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attnum>0 AND NOT a.attisdropped),
catalog AS (SELECT name,jsonb_agg(descriptor ORDER BY attnum) AS descriptors FROM columns GROUP BY name)
SELECT jsonb_build_object('version',2,'schema',(SELECT jsonb_object_agg(name,descriptors) FROM catalog),'schemaText',(SELECT jsonb_object_agg(name,descriptors)::text FROM catalog),'tables',jsonb_build_object(
${nationalBusinessTables.map(t=>`'${t}',(SELECT COALESCE(jsonb_agg(to_jsonb(r)::text ORDER BY to_jsonb(r)::text),'[]'::jsonb) FROM ${t} r)`).join(',\n')}))`
function nationalJson(value:unknown):string{
 if(value===null||typeof value==='string'||typeof value==='boolean')return JSON.stringify(value)
 if(typeof value==='number'){expect(Number.isFinite(value)).toBe(true);return JSON.stringify(value)}
 if(Array.isArray(value)){expect(Object.keys(value)).toEqual(Array.from({length:value.length},(_,i)=>String(i)));expect(Reflect.ownKeys(value).length).toBe(value.length+1);return '['+value.map(nationalJson).join(',')+']'}
 expect(value).not.toBeNull();expect(typeof value).toBe('object');expect(Object.getPrototypeOf(value)).toBe(Object.prototype)
 const row=value as Row;expect(Reflect.ownKeys(row).length).toBe(Object.keys(row).length);return '{'+Object.keys(row).sort().map(k=>JSON.stringify(k)+':'+nationalJson(row[k])).join(',')+'}'
}
function nationalBusinessFrame(read:Sql):NationalBusinessFrame{
 const v=structuredClone(read<unknown>(nationalBusinessQuery));nationalJson(v)
 expect(Object.keys(v as Row).sort()).toEqual(['version','schema','schemaText','tables'].sort());const frame=v as NationalBusinessFrame
 expect(frame.version).toBe(2);expect(typeof frame.schemaText).toBe('string');expect(JSON.parse(frame.schemaText)).toEqual(frame.schema)
 for(const key of ['schema','tables'] as const)expect(Object.keys(frame[key]).sort()).toEqual([...nationalBusinessTables].sort())
 for(const table of nationalBusinessTables){
  const cols=frame.schema[table];expect(Array.isArray(cols)&&cols.length>0).toBe(true)
  const names=new Set<string>();let position=0
  for(const col of cols){expect(Object.keys(col).sort()).toEqual(['name','position','type','notNull','default','generated'].sort())
   expect(typeof col.name==='string'&&col.name.length>0&&!names.has(col.name)).toBe(true);names.add(col.name)
   expect(Number.isSafeInteger(col.position)&&col.position>position).toBe(true);position=col.position
   expect(typeof col.type==='string'&&col.type.length>0).toBe(true);expect(typeof col.notNull).toBe('boolean')
   expect(col.default===null||typeof col.default==='string').toBe(true);expect(['','s','v']).toContain(col.generated)
  }
  expect(Array.isArray(frame.tables[table])).toBe(true)
  for(const text of frame.tables[table]){expect(typeof text).toBe('string');const row=JSON.parse(text) as Row;expect(row!==null&&typeof row==='object'&&!Array.isArray(row)).toBe(true);expect(Object.keys(row).sort()).toEqual([...names].sort());for(const col of cols)if(col.notNull)expect(row[col.name]).not.toBeNull()}
 }
 return frame
}
